{"input": "Module[{seed = {1, 0, 1, 1, 0}, steps = 30, evolve, deltaReflect, grid},

  (* Define recursive delta-based evolution with harmonic reflection *)
  deltaReflect[state_List] := Module[{n = Length[state], delta},
    delta = Table[Mod[state[[Mod[i - 1, n, 1]]] + state[[i + 1]] - 2 state[[i]], 2], {i, 2, n - 1}];
    Prepend[Append[delta, state[[-1]]], state[[1]]]
  ];

  evolve[s_, 0] := {s};
  evolve[s_, t_] := Prepend[evolve[deltaReflect[s], t - 1], s];

  grid = ArrayPlot[evolve[seed, steps], PixelConstrained -> 5, ColorRules -> {1 -> Black, 0 -> White}, Frame -> False]
] "}

