  deltaReflect[state_List] := Module[{n = Length[state], delta},
    delta = Table[normalize[Abs[state[[Mod[i - 1, n, 1]]] - state[[Mod[i + 1, n, 1]]]]], {i, 1, n}];
    Join[state, delta]
  ];

  evolve[s_, 0] := {s};
  evolve[s_, t_] := Prepend[evolve[deltaReflect[s], t - 1], s];

  grid = ArrayPlot[
    Map[normalize /@ # &, evolve[seed, steps]],
    PixelConstrained -> 5,
    ColorRules -> {1 -> Black, 0 -> White},
    Frame -> False
  ]
] "}

